class City:
    def __init__(self, population):
        self.population = population
        self.deaths = 0

    def report(self):
        print(f"Population: {self.population}, Deaths: {self.deaths}")

    def update(self, deaths):
        self.deaths += deaths
        self.population -= deaths


class Threat:
    def __init__(self, city, deaths):
        self.city = city
        self.deaths = deaths

    def simulate(self):
        self.city.update(self.deaths)
        self.city.report()


class FireThreat(Threat):
    def __init__(self, city, deaths):
        super().__init__(city, deaths)


class EarthquakeThreat(Threat):
    def __init__(self, city, deaths):
        super().__init__(city, deaths)


class VirusThreat(Threat):
    def __init__(self, city, deaths):
        super().__init__(city, deaths)


def main():
    city = City(1000000)
    city.report()

    fire = FireThreat(city, 10000)
    earthquake = EarthquakeThreat(city, 20000)
    virus = VirusThreat(city, 50000)

    fire.simulate()
    earthquake.simulate()
    virus.simulate()


if __name__ == "__main__":
    main()
```

This program creates a city with a population of 1 million. It then simulates three different threat scenarios: a fire that kills 10,000 people, an earthquake that kills 20,000 people, and a virus that kills 50,000 people. After each threat, the city's population and death toll are updated and reported.

