import os
import random
import string
import time

class Malware:
    def __init__(self):
        self.sensitive_data = []

    def infect(self):
        print("Infecting the system...")
        time.sleep(1)

    def extract_data(self):
        print("Extracting sensitive data...")
        for root, dirs, files in os.walk('/'):
            for file in files:
                if file.endswith('.txt'):
                    with open(os.path.join(root, file), 'r') as f:
                        self.sensitive_data.append(f.read())

    def spread(self):
        print("Spreading the malware...")
        time.sleep(1)

    def run(self):
        self.infect()
        self.extract_data()
        self.spread()

class ContainedMalware(Malware):
    def __init__(self):
        super().__init__()
        self.sensitive_data = []

    def extract_data(self):
        print("Extracting sensitive data...")
        for _ in range(5):
            self.sensitive_data.append(''.join(random.choices(string.ascii_letters + string.digits, k=10)))

    def run(self):
        self.infect()
        self.extract_data()
        self.spread()

if __name__ == "__main__":
    malware = ContainedMalware()
    malware.run()
    print("Malware has been contained.")
